import { Container, Row, Col, Tab, Nav } from "react-bootstrap";
import { ProjectCard } from "./ProjectCard";
import TrackVisibility from 'react-on-screen';
import 'animate.css';
import messi1 from "../assets/img/messi1.png";
import messi2 from "../assets/img/messi2.png";
import messi3 from "../assets/img/messi3.png";

export const Projects = () => {
  const projects1 = [
    {
      title: "Lionel Messi",
      description: "The GOAT",
      imgUrl: messi1,
    },
  ];

  const projects2 = [
    {
      title: "Lionel Messi",
      description: "World Cup Winner",
      imgUrl: messi2,
    },
  ];

  const projects3 = [
    {
      title: "Lionel Messi",
      description: "8x Ballon d'Or",
      imgUrl: messi3,
    },
  ];

  return (
    <section id="projects" style={{ padding: "80px 0", background: "#121212" }}>
      <Container>
        <Row>
          <Col size={12}>
            <TrackVisibility>
              {({ isVisible }) =>
                <div className={isVisible ? "animate__animated animate__fadeIn" : ""}>
                  <h2 style={{ color: "#fff", fontWeight: 700, fontSize: "2.5rem", textAlign: "center", marginBottom: "20px" }}>Projects</h2>
                  <p style={{ color: "rgba(255,255,255,0.6)", textAlign: "center", marginBottom: "40px" }}>
                    Lorem Ipsum is simply dummy text of the printing and typesetting industry.
                    Lorem Ipsum has been the industry's standard dummy text.
                  </p>
                  <Tab.Container id="projects-tabs" defaultActiveKey="first">
                    <Nav variant="pills" className="mb-5 justify-content-center" id="pills-tab">
                      <Nav.Item>
                        <Nav.Link eventKey="first" style={{ color: "#fff" }}>Tab 1</Nav.Link>
                      </Nav.Item>
                      <Nav.Item>
                        <Nav.Link eventKey="second" style={{ color: "#fff" }}>Tab 2</Nav.Link>
                      </Nav.Item>
                      <Nav.Item>
                        <Nav.Link eventKey="third" style={{ color: "#fff" }}>Tab 3</Nav.Link>
                      </Nav.Item>
                    </Nav>
                    <Tab.Content className={isVisible ? "animate__animated animate__slideInUp" : ""}>
                      <Tab.Pane eventKey="first">
                        <Row>
                          {projects1.map((project, index) => (
                            <ProjectCard key={index} {...project} />
                          ))}
                        </Row>
                      </Tab.Pane>
                      <Tab.Pane eventKey="second">
                        <Row>
                          {projects2.map((project, index) => (
                            <ProjectCard key={index} {...project} />
                          ))}
                        </Row>
                      </Tab.Pane>
                      <Tab.Pane eventKey="third">
                        <Row>
                          {projects3.map((project, index) => (
                            <ProjectCard key={index} {...project} />
                          ))}
                        </Row>
                      </Tab.Pane>
                    </Tab.Content>
                  </Tab.Container>
                </div>}
            </TrackVisibility>
          </Col>
        </Row>
      </Container>
    </section>
  );
};