import { Col } from "react-bootstrap";

export const ProjectCard = ({ title, description, imgUrl }) => {
  return (
    <Col size={12} sm={6} md={4}>
      <div style={{
        position: "relative",
        borderRadius: "10px",
        overflow: "hidden",
        margin: "10px",
        cursor: "pointer"
      }}>
        <img src={imgUrl} alt={title} style={{ width: "100%", height: "200px", objectFit: "cover" }} />
        <div style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          background: "linear-gradient(90.21deg, #aa367c -5.91%, #4a2fbd 111.58%)",
          padding: "15px",
          transform: "translateY(100%)",
          transition: "transform 0.3s ease"
        }}
        onMouseEnter={e => e.currentTarget.style.transform = "translateY(0)"}
        onMouseLeave={e => e.currentTarget.style.transform = "translateY(100%)"}>
          <h4 style={{ color: "#fff", fontWeight: 700 }}>{title}</h4>
          <span style={{ color: "rgba(255,255,255,0.8)" }}>{description}</span>
        </div>
      </div>
    </Col>
  );
};